const body = $json.body || {};
if (!body.tenant_id || !body.user_id || !body.message) throw new Error('Solicitud de chat incompleta');

// Habilitar solo cuando n8n y el ERP tengan el mismo secreto configurado.
if ($env.ERP_RAG_ENFORCE_HMAC === 'true') {
  const crypto = require('crypto');
  const timestamp = $json.headers?.['x-erp-timestamp'];
  const received = $json.headers?.['x-erp-signature'];
  const raw = $json.rawBody || JSON.stringify(body);
  if (!timestamp || !received || Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) throw new Error('Solicitud vencida o incompleta');
  const expected = 'sha256=' + crypto.createHmac('sha256', $env.ERP_RAG_WEBHOOK_SECRET).update(`${timestamp}.${raw}`).digest('hex');
  const a = Buffer.from(received); const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Firma HMAC inválida');
}

const conversation = body.conversation_id || 'principal';
return [{ json: { ...body, session_key: `${body.tenant_id}:${body.user_id}:${conversation}` } }];
